/**
 * Native Arabic pages — the SEO-friendly replacement for the old
 * Google-Translate-widget approach. Each `ArPage` is a fully self-contained,
 * professionally written Arabic page served at `/ar/{slug}` (Arabic slug,
 * per the site's URL spec) and cross-linked back to its English original via
 * `enPath`, which drives hreflang, canonical alternates, and the language
 * switcher.
 *
 * This is Phase 1 of the Arabic rollout: the full routing/RTL/hreflang/schema
 * pipeline, proven end-to-end with a flagship page per template type (a
 * service pillar, an airport, a city, a route, a hotel transfer, a blog
 * post, plus About/Contact). Bulk-translating the remaining ~350 pages is a
 * scoped follow-on that reuses this exact same registry shape — just append
 * more `ArPage` objects; no template or routing changes are needed.
 */

import type { JourneyContent } from "@/components/journey/JourneyPageView";
import type { DistanceGuideV2Content } from "@/components/distance-v2/DistanceGuideV2View";
import type { JourneyV2Content } from "@/components/journey-v2/JourneyGuideV2View";
import type { PointTransferV2Content } from "@/components/point-transfer-v2/PointTransferV2View";

/** Natural Arabic city names for the 6 cities with point-transfer pages —
 * used for breadcrumbs/schema areaServed on pointTransferV2 pages, since
 * data/cities.ts only carries the English name. */
export const pointTransferCityNameAr: Record<string, string> = {
  jeddah: "جدة",
  makkah: "مكة المكرمة",
  dammam: "الدمام",
  madinah: "المدينة المنورة",
  riyadh: "الرياض",
  alula: "العلا",
};
import type { ServiceV2Content } from "@/components/services/ServiceV2View";
import type { LegalPageViewContent } from "@/components/legal/LegalPageView";
import type { ContactPageViewContent } from "@/components/contact/ContactPageView";
import type { QuotePageViewContent } from "@/components/quote/QuotePageView";
import type { ServicesHubContent } from "@/components/services-hub/ServicesHubView";

export type ArPageType =
  | "about"
  | "contact"
  | "service"
  | "airport"
  | "city"
  | "route"
  | "hotel-transfer"
  | "blog"
  /** Ziyarat / historic-site visit pages — distinct from "route" (intercity
   * transfers) so schema and hero selection can represent them correctly. */
  | "attraction"
  /** Arabic counterpart of /cities/{city} — airport-facts + hotel-table hub.
   * Distinct from "city" (which maps to /taxi-service/{city}, a different
   * page). Rendered by a dedicated branch in app/ar/[...slug]/page.tsx that
   * reads data/hotels.ts / data/airports.ts / lib/city-hub-facts.ts directly,
   * not via `sections` below (kept only as a plain-text fallback/summary). */
  | "city-hub"
  /** Arabic counterpart of /distance/{slug} — informational "how far / how
   * long" pages, deliberately NOT bookable: no QuoteForm, VehicleOptions, or
   * booking CTASection, matching the English distance-page template. Uses
   * the distance-specific fields below (quickAnswer, transportOptions,
   * sources, ctaRoutePath) instead of forcing the generic booking flow. */
  | "distance"
  /** Arabic counterpart of a "rich journey" distance page (see
   * data/journey-pages.ts / components/journey/JourneyPageView.tsx) — same
   * deliberately distinct visual design, rendered via the `journey` field
   * below instead of `sections`/`quickAnswer`/etc. */
  | "journey"
  /** Arabic counterpart of a "Road Distance Guide V2" page (see
   * data/distance-guide-v2.ts / components/distance-v2/DistanceGuideV2View.tsx)
   * — a third, deliberately distinct informational design, rendered via the
   * `distanceV2` field below instead of `sections`/`quickAnswer`/`journey`. */
  | "distanceV2"
  /** Arabic counterpart of a "Journey V2" page (see
   * data/journey-guide-v2.ts / components/journey-v2/JourneyGuideV2View.tsx)
   * — the premium long-distance planning-guide design replacing the old
   * "journey" type above, rendered via the `journeyV2` field below. */
  | "journeyV2"
  /** Arabic counterpart of a rebuilt service page (see
   * data/service-pages-v2/*.ts / components/services/ServiceV2View.tsx) —
   * replaces the old "service" type's fixed sections/faqs template with the
   * same block-composed design used by the English pages, via the
   * `serviceV2` field below. */
  | "serviceV2"
  /** Native Arabic Privacy Policy / Terms & Conditions page (see
   * components/legal/LegalPageView.tsx) — no Arabic legal pages existed
   * before this; rendered via the `legal` field below instead of
   * `sections`/`faqs`. */
  | "legal"
  /** Native Arabic Contact page (see components/contact/ContactPageView.tsx)
   * — replaces the old "contact" type's fixed sections/faqs template with
   * the dedicated conversational contact-page design, via the `contactV2`
   * field below. Same slug as the original "contact" entry it replaces. */
  | "contactV2"
  /** Native Arabic Get a Quote page (see components/quote/QuotePageView.tsx)
   * — no Arabic quote page existed before this; rendered via the `quoteV2`
   * field below instead of `sections`/`faqs`. */
  | "quoteV2"
  /** Native Arabic Services hub page (see
   * components/services-hub/ServicesHubView.tsx) — no Arabic services hub
   * existed before this; rendered via the `servicesHub` field below instead
   * of `sections`/`faqs`. */
  | "servicesV2"
  /** Arabic counterpart of a "Point Transfer V2" page (see
   * data/point-transfer-v2/*.ts / components/point-transfer-v2/
   * PointTransferV2View.tsx) — hotel/attraction/port/railway/service point
   * transfers under /{city}/{slug}, rendered via the `pointTransferV2` field
   * below instead of `sections`/`faqs`. Replaces the old generic "attraction"
   * type previously used (loosely) for these same pages. */
  | "pointTransferV2";

export interface ArFaq {
  question: string;
  answer: string;
}

export interface ArSection {
  heading: string;
  paragraphs: string[];
}

export interface ArPage {
  /** URL segment after /ar/ — Arabic script, unique, matches the site's Arabic-slug spec. */
  slug: string;
  type: ArPageType;
  /** The canonical English path this page is the Arabic translation of (drives hreflang). */
  enPath: string;
  /**
   * Set when this is a second Arabic article on the same topic as `enPath`
   * rather than its translation — the English page already pairs with a
   * different entry. Such a page emits no hreflang to `enPath` (only its own
   * Arabic self-reference) and is skipped by the English→Arabic lookups, so
   * every hreflang pair stays one-to-one and reciprocal. `enPath` is still
   * used for non-hreflang purposes (language switcher, related-guide keys).
   */
  notEnTranslation?: true;
  /** <title> / metaTitle (≤60 chars is the target, Arabic character count). */
  metaTitle: string;
  metaDescription: string;
  h1: string;
  intro: string;
  sections: ArSection[];
  faqs: ArFaq[];
  /** Arabic breadcrumb trail: {name, path}, path already prefixed with /ar. */
  breadcrumbs: { name: string; path: string }[];
  heroImage?: string;
  heroAlt?: string;
  /** Distance/duration chips, for route/airport/hotel-transfer pages. */
  distance?: string;
  duration?: string;
  /**
   * Rich HTML body — tables, lists, headings, inline links — mirroring the
   * English blog's `Blog.content` field. Used for `type: "blog"` pages that
   * need real formatting (comparison tables, checklists) beyond what plain
   * `sections` paragraphs can express. When present, this renders instead of
   * `sections` via the same `BlogContent`/`.blog-prose` treatment the English
   * blog uses (RTL-aware styling already exists in globals.css). `sections`
   * should still be filled in as a plain-text fallback/summary so non-blog
   * consumers of this page's data (e.g. schema descriptions) keep working.
   */
  contentHtml?: string;
  /** type: "distance" only — the labelled quick-answer box at the top of the page. */
  quickAnswer?: {
    drivingDistance: string;
    drivingTime: string;
    straightLineDistance?: string;
    note: string;
  };
  /** type: "distance" only — the "how to travel" transport-mode cards. */
  transportOptions?: {
    mode: string;
    suitability: string;
    duration: string;
    advantages: string;
    limitations: string;
  }[];
  /** type: "distance" only — cited sources, rendered with rel="nofollow". */
  sources?: { label: string; url: string }[];
  /** type: "distance" only — the single contextual CTA to the matching commercial
   * route page. Points at the Arabic /ar/{slug} route page when one already
   * exists, otherwise falls back to the English /routes/{slug} page rather
   * than forcing a translation that doesn't exist yet. */
  ctaRoutePath?: string;
  ctaLabel?: string;
  /** type: "distance" only — "related pages" links (sibling Arabic distance
   * pages, Arabic city hubs, etc.), separate from the breadcrumb trail. */
  relatedLinks?: { label: string; href: string }[];
  /** type: "journey" only — the full rich-design content (Arabic strings
   * throughout), rendered via the shared JourneyPageView component with
   * Arabic labels. See components/journey/JourneyPageView.tsx. */
  journey?: JourneyContent;
  /** type: "journey" only — origin/destination labels for the hero's
   * from → to visual (Arabic city/place names). */
  journeyFrom?: string;
  journeyTo?: string;
  /** type: "distanceV2" only — the full "Road Distance Guide V2" content
   * (Arabic strings throughout), rendered via the shared
   * DistanceGuideV2View component with Arabic labels. */
  distanceV2?: DistanceGuideV2Content;
  /** type: "distanceV2" only — origin/destination labels for the masthead's
   * from → to visual (Arabic city/place names). */
  distanceV2From?: string;
  distanceV2To?: string;
  /** type: "journeyV2" only — the full "Journey V2" content (Arabic strings
   * throughout), rendered via the shared JourneyGuideV2View component with
   * Arabic labels. */
  journeyV2?: JourneyV2Content;
  /** type: "journeyV2" only — origin/destination labels for the hero's
   * route-line visual (Arabic city/place names). */
  journeyV2From?: string;
  journeyV2To?: string;
  /** type: "serviceV2" only — the full rebuilt service-page content (Arabic
   * strings throughout), rendered via the shared ServiceV2View component. */
  serviceV2?: ServiceV2Content;
  /** type: "legal" only — the full Privacy Policy / Terms & Conditions
   * content (Arabic strings throughout), rendered via the shared
   * LegalPageView component. */
  legal?: LegalPageViewContent;
  /** type: "contactV2" only — the full Contact page content (Arabic strings
   * throughout), rendered via the shared ContactPageView component. */
  contactV2?: ContactPageViewContent;
  /** type: "quoteV2" only — the full Get a Quote page content (Arabic
   * strings throughout), rendered via the shared QuotePageView component. */
  quoteV2?: QuotePageViewContent;
  /** type: "servicesV2" only — the full Services hub page content (Arabic
   * strings throughout), rendered via the shared ServicesHubView component. */
  servicesHub?: ServicesHubContent;
  /** type: "pointTransferV2" only — the full point-transfer content (Arabic
   * strings throughout), rendered via the shared PointTransferV2View
   * component with Arabic labels. */
  pointTransferV2?: PointTransferV2Content;
  /** type: "pointTransferV2" only — origin/destination labels for the hero's
   * from → to visual (Arabic place names); false for named-offering "service"
   * pages that read as a single destination. */
  pointTransferV2From?: string;
  pointTransferV2To?: string;
  pointTransferV2IsPointToPoint?: boolean;
  /** type: "pointTransferV2" only — the city slug segment for schema/labels
   * (e.g. "jeddah"), matching the English page's citySlug. */
  pointTransferV2CitySlug?: string;
}

// The full Arabic content (~442 pages, ~2.7 MB of source) is built only when
// something actually needs it, via getArPages(). It used to be a top-level
// `export const arPages = [...]`, which meant the first Arabic request on every
// Cloudflare Worker instance allocated the entire dataset just to load the
// route module — even for prerendered pages served straight from cache, whose
// render code never runs. Under sustained crawling that initialization failed
// (HTTP 500 from OpenNext on Arabic URLs only, each fine when requested alone).
// Behind a function the content is only built at build time and for the rare
// runtime render; nav/sitemap/redirect code uses the lightweight
// data/translations/ar-index.ts instead.
let _arPages: ArPage[] | undefined;
export function getArPages(): ArPage[] {
  return (_arPages ??= buildArPages());
}

